function ncLabel(value){return APP_I18N.current()==='ru'?(NC_RU_LABELS[value]||value):String(value||'').replaceAll('_',' ');}
function ncBindActivation(selector, root, activate){
  $$(selector,root).forEach(element=>{
    element.onclick=()=>activate(element);
    element.onkeydown=event=>{
      if(event.key!=='Enter'&&event.key!==' ')return;
      event.preventDefault();activate(element);
    };
  });
}

const NC_AUDIO = (() => {
  let context=null,master=null,ambient=null,muted=localStorage.getItem('ncnet:muted')==='1',volume=Math.max(0,Math.min(1,Number(localStorage.getItem('ncnet:volume')??.55)));
  function tone(frequency=520,duration=.06,type='square',gain=.025){
    if(!context||muted)return;const osc=context.createOscillator(),amp=context.createGain();
    osc.type=type;osc.frequency.value=frequency;amp.gain.setValueAtTime(gain,context.currentTime);amp.gain.exponentialRampToValueAtTime(.0001,context.currentTime+duration);osc.connect(amp).connect(master);osc.start();osc.stop(context.currentTime+duration);
  }
  function start(){
    if(context){if(context.state==='suspended')context.resume();return;}
    const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return;
    context=new AudioContext();master=context.createGain();master.gain.value=volume;master.connect(context.destination);
    const osc=context.createOscillator(),gain=context.createGain(),filter=context.createBiquadFilter();osc.type='sine';osc.frequency.value=48;filter.type='lowpass';filter.frequency.value=120;gain.gain.value=muted?0:.015;osc.connect(filter).connect(gain).connect(master);osc.start();ambient={osc,gain};document.addEventListener('visibilitychange',()=>{if(ambient&&context)ambient.gain.gain.setTargetAtTime(document.hidden?0:(muted?0:.015),context.currentTime,.08);},{once:false});
    tone(760,.08,'sawtooth',.035);setTimeout(()=>tone(1120,.12,'square',.025),90);
  }
  function update(){const button=document.querySelector('#audio-toggle');if(button){button.textContent=muted?'🔇':'🔊';button.title=muted?T('Enable NC//NET audio','Включить звук NC//NET'):T('Mute NC//NET audio','Выключить звук NC//NET');}}
  function setVolume(value){volume=Math.max(0,Math.min(1,Number(value)));localStorage.setItem('ncnet:volume',String(volume));if(master&&context)master.gain.setTargetAtTime(volume,context.currentTime,.05);}
  function getVolume(){return volume;}
  function toggle(){start();muted=!muted;localStorage.setItem('ncnet:muted',muted?'1':'0');if(ambient)ambient.gain.gain.setTargetAtTime(muted?0:.015,context.currentTime,.08);if(!muted)tone(880,.08);update();}
  function maybeGate(){
    update();if(localStorage.getItem('ncnet:connected')==='1')return;
    const gate=document.createElement('div');gate.className='nc-connect-gate';gate.setAttribute('role','dialog');gate.setAttribute('aria-modal','true');gate.setAttribute('aria-label',T('NC//NET secure connection','Защищённое соединение NC//NET'));gate.innerHTML=`<div class="nc-connect-terminal"><div class="brand-name">NC<b>//NET</b></div><div class="scanline-text">${T('ENCRYPTED NIGHT CITY RELAY','ЗАШИФРОВАННЫЙ КАНАЛ НАЙТ-СИТИ')}</div><button class="btn-primary" id="nc-connect">${T('ESTABLISH SECURE CONNECTION','УСТАНОВИТЬ ЗАЩИЩЁННОЕ СОЕДИНЕНИЕ')}</button><button class="btn-sm" id="nc-connect-silent">${T('CONNECT WITHOUT AUDIO','ПОДКЛЮЧИТЬСЯ БЕЗ ЗВУКА')}</button></div>`;document.body.appendChild(gate);
    $('#nc-connect',gate).focus();
    $('#nc-connect',gate).onclick=()=>{localStorage.setItem('ncnet:connected','1');muted=false;localStorage.setItem('ncnet:muted','0');start();update();gate.remove();};
    $('#nc-connect-silent',gate).onclick=()=>{localStorage.setItem('ncnet:connected','1');muted=true;localStorage.setItem('ncnet:muted','1');update();gate.remove();};
  }
  return {start,toggle,tone,update,maybeGate,setVolume,getVolume};
})();

function ncLocation(id){return NC_LOCATIONS.find(location=>location.id===id);}
function ncDistrictName(id){const location=ncLocation(id);if(!location)return id||T('Classified','Секретно');return location.parent_id?`${T(location.parent_en,location.parent_ru)} // ${T(location.en,location.ru)}`:T(location.en,location.ru);}
function ncLocationOptions(selected,emptyLabel='—'){return `<option value="">${esc(emptyLabel)}</option>`+NC_DISTRICTS.map(district=>`<optgroup label="${esc(T(district.en,district.ru))}"><option value="${district.id}" ${selected===district.id?'selected':''}>${T('General / Unspecified','Общее / без уточнения')}</option>${district.children.map(child=>`<option value="${child.id}" ${selected===child.id?'selected':''}>${esc(T(child.en,child.ru))}</option>`).join('')}</optgroup>`).join('');}
function ncDistrictFilters(){return NC_DISTRICTS.map(district=>district.children.length?`<details class="nc-location-group"><summary>${esc(T(district.en,district.ru))}</summary><button data-contract-district="${district.id}">${T('All / General','Все / общее')}</button>${district.children.map(child=>`<button data-contract-district="${child.id}">${esc(T(child.en,child.ru))}</button>`).join('')}</details>`:`<button data-contract-district="${district.id}">${esc(T(district.en,district.ru))}</button>`).join('');}
function ncLocationMatches(filter,locationId){if(!filter)return true;if(filter===locationId)return true;const location=ncLocation(locationId);return Boolean(location&&location.parent_id===filter);}
function ncMapThemeMode(){return localStorage.getItem('ncnet:map-palette')!=='original';}
function ncSetupZoomPan(stage){
  if(stage.querySelector('.nc-map-zoom-in'))return;
  var scale=1,panX=0,panY=0,minScale=1,maxScale=4;
  var wrap=document.createElement('div');
  wrap.className='nc-map-zoom-wrap';
  wrap.style.cssText='position:absolute;inset:0;transform-origin:0 0;transition:transform .12s ease-out;will-change:transform';
  var img=stage.querySelector('.nc-map-image');
  var tint=stage.querySelector('.nc-map-tint');
  var ov=stage.querySelector('.nc-map-overlay');
  if(img)wrap.appendChild(img);
  if(tint)wrap.appendChild(tint);
  if(ov)wrap.appendChild(ov);
  stage.insertBefore(wrap,stage.firstChild);
  var apply=function(){wrap.style.transform='translate('+panX+'px,'+panY+'px) scale('+scale+')';};
  var pos=10;
  var addBtn=function(cls,label,fn){var b=document.createElement('button');b.className='nc-map-zoom-btn '+cls;b.type='button';b.textContent=label;b.style.cssText='position:absolute;z-index:4;right:10px;width:32px;height:32px;font:bold 16px Orbitron;background:color-mix(in srgb,var(--panel) 88%,transparent);backdrop-filter:blur(6px);border:1px solid var(--line);color:var(--text);cursor:pointer';b.style.top=pos+'px';pos+=36;b.onclick=fn;stage.appendChild(b);return b;};
  addBtn('nc-map-zoom-in','+',function(){scale=Math.min(maxScale,scale*1.3);apply();});
  addBtn('nc-map-zoom-out','\u2212',function(){scale=Math.max(minScale,scale/1.3);if(scale<=1.01){panX=0;panY=0;}apply();});
  stage.addEventListener('wheel',function(e){e.preventDefault();var rect=stage.getBoundingClientRect();var mx=e.clientX-rect.left,my=e.clientY-rect.top;var old=scale;scale=e.deltaY<0?Math.min(maxScale,scale*1.12):Math.max(minScale,scale/1.12);panX=mx-(mx-panX)*(scale/old);panY=my-(my-panY)*(scale/old);if(scale<=1.01){panX=0;panY=0;}apply();},{passive:false});
  var drag=false,sx=0,sy=0,px=0,py=0;
  stage.addEventListener('mousedown',function(e){if(scale<=1)return;drag=true;sx=e.clientX;sy=e.clientY;px=panX;py=panY;stage.style.cursor='grabbing';});
  window.addEventListener('mousemove',function(e){if(!drag)return;panX=px+(e.clientX-sx);panY=py+(e.clientY-sy);apply();});
  window.addEventListener('mouseup',function(){drag=false;stage.style.cursor='';});
  // Touch pinch
  var pinchDist=0,pinchScale=1;
  stage.addEventListener('touchstart',function(e){if(e.touches.length===2){e.preventDefault();var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY;pinchDist=Math.sqrt(dx*dx+dy*dy);pinchScale=scale;}},{passive:false});
  stage.addEventListener('touchmove',function(e){if(e.touches.length===2&&pinchDist>0){e.preventDefault();var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY;var d=Math.sqrt(dx*dx+dy*dy);scale=Math.max(minScale,Math.min(maxScale,pinchScale*(d/pinchDist)));if(scale<=1.01){panX=0;panY=0;}apply();}},{passive:false});
  apply();
}
function ncBindMapControls(root){$$('.nc-map-stage',root).forEach(function(stage){ncSetupZoomPan(stage);});
$$('[data-map-palette]',root).forEach(button=>button.onclick=()=>{const themed=!button.closest('.nc-map-stage').classList.contains('theme-map');localStorage.setItem('ncnet:map-palette',themed?'theme':'original');$$('.nc-map-stage',root).forEach(stage=>stage.classList.toggle('theme-map',themed));$$('[data-map-palette]',root).forEach(control=>{control.setAttribute('aria-pressed',themed?'true':'false');control.textContent=themed?T('THEME MAP','ЦВЕТА ТЕМЫ'):T('ORIGINAL MAP','ОРИГИНАЛ');});});}
function ncDate(ts){return ts?new Date(Number(ts)*1000).toLocaleString(APP_I18N.current()==='ru'?'ru-RU':'en-US',{dateStyle:'medium',timeStyle:'short'}):T('Unscheduled','Время не назначено');}
function ncDateTimeInput(ts){if(!ts)return '';const date=new Date(Number(ts)*1000-new Date().getTimezoneOffset()*60000);return date.toISOString().slice(0,16);}
function ncReward(contract){if(contract.reward_mode==='exact')return money(contract.reward_exact);if(contract.reward_mode==='range')return `${money(contract.reward_min)}–${money(contract.reward_max)}`;if(contract.reward_mode==='negotiable')return contract.reward_text||T('Negotiable','Договорная');return T('Classified','Скрыто');}
function ncAuthorAvatar(author){if(author?.avatar_media_id)return `<img class="nc-avatar" src="/api/media/${esc(author.avatar_media_id)}" alt="">`;return `<span class="nc-avatar placeholder">${esc((author?.display_name||'?').slice(0,1).toUpperCase())}</span>`;}
function ncContractCard(contract){const poster=contract.participants?.find(item=>item.role_key==='poster')||contract.participants?.[0];return `<article class="nc-contract-card ${esc(ncLabel(contract.status))}" data-contract-open="${contract.id}" role="button" tabindex="0" aria-label="${esc(T('Open Contract: ','Открыть Contract: ')+contract.title)}" style="--persona:${esc(poster?.accent_color||'#00e5ff')}">${contract.cover_media_id?`<div class="nc-contract-cover-frame"><img class="nc-contract-cover" src="/api/media/${esc(contract.cover_media_id)}" alt="${esc(contract.title)}" loading="lazy"></div>`:''}<div class="nc-contract-scan"><span class="tag">${esc(ncLabel(contract.status).toUpperCase())}</span><span class="risk-${esc(contract.risk_level)}">${esc(ncLabel(contract.risk_level).toUpperCase())}</span></div><h3 class="user-content">${esc(contract.title)}</h3><p class="small user-content">${esc(contract.teaser||contract.public_brief.slice(0,180))}</p><div class="chips"><span class="chip">⌖ ${esc(ncDistrictName(contract.district_id))}</span><span class="chip">€ ${esc(ncReward(contract))}</span><span class="chip">◷ ${esc(ncDate(contract.scheduled_at))}</span></div><div class="row mt"><span class="small user-content">${esc(poster?.display_name||'NC//NET')}</span><span class="small muted">${contract.crew_capacity?`${contract.crew_count}/${contract.crew_capacity}`:T('open crew','без лимита')}${contract.waitlist_count?` · +${contract.waitlist_count} ${T('waitlist','резерв')}`:''}</span></div></article>`;}

const NC_MAP_LAYERS = {contracts: true, poi: true, vendors: true};
function ncLayeredMapHtml(contracts, locations, vendors) {
  var themed = ncMapThemeMode();
  var contractMarkers = (contracts || []).map(function(contract, index) {
    var anchor = NC_MAP_COORDS[contract.district_id] || [535, 470];
    var jitter = ((contract.id * 37) % 46) - 23, jitterY = ((contract.id * 19) % 38) - 19;
    var x = Math.max(28, Math.min(972, anchor[0] + jitter));
    var y = Math.max(28, Math.min(972, anchor[1] + jitterY));
    return '<g class="nc-marker nc-layer-contracts" data-contract-open="' + contract.id + '" role="button" tabindex="0" transform="translate(' + x + ' ' + y + ')" filter="url(#mapGlow)"><circle class="pulse" r="17"></circle><circle r="11"></circle><text y="4" text-anchor="middle">' + (index + 1) + '</text><title>' + esc(contract.title) + '</title></g>';
  }).join('');
  var poiMarkers = (locations || []).map(function(loc) {
    return '<g class="nc-marker nc-layer-poi nc-poi-marker" data-poi-open="' + esc(loc.id) + '" role="button" tabindex="0" transform="translate(' + Math.round(loc.x) + ' ' + Math.round(loc.y) + ')"><circle r="8" fill="var(--cyan,#00e5ff)" stroke="#07101b" stroke-width="2"></circle><text y="3" text-anchor="middle" font-size="10">' + (typeof locationKindIcon === 'function' ? locationKindIcon(loc.kind) : '📍') + '</text><title>' + esc(loc.name_en || loc.name_ru) + '</title></g>';
  }).join('');
  var vendorMarkers = (vendors || []).filter(function(v) { return v.location_id; }).map(function(v) {
    var loc = (locations || []).find(function(l) { return l.id === v.location_id; });
    if (!loc) return '';
    var vx = Math.round(loc.x) + 15, vy = Math.round(loc.y) - 10;
    return '<g class="nc-marker nc-layer-vendors nc-vendor-marker" data-vendor-open="' + esc(v.id) + '" role="button" tabindex="0" transform="translate(' + vx + ' ' + vy + ')"><circle r="9" fill="var(--yellow,#ffd500)" stroke="#07101b" stroke-width="2"></circle><text y="3" text-anchor="middle" font-size="9">' + esc(v.icon || '◈') + '</text><title>' + esc(v.name_en) + '</title></g>';
  }).join('');
  var layerBtns = '<div class="nc-map-layers" style="position:absolute;z-index:5;left:10px;bottom:10px;display:flex;gap:4px">';
  ['contracts', 'poi', 'vendors'].forEach(function(key) {
    var labels = {contracts: ['SIGNALS', 'СИГНАЛЫ'], poi: ['PLACES', 'МЕСТА'], vendors: ['SHOPS', 'МАГАЗИНЫ']};
    var L = labels[key];
    layerBtns += '<button class="btn-sm nc-layer-btn ' + (NC_MAP_LAYERS[key] ? 'active' : '') + '" data-layer="' + key + '" style="font:600 9px Orbitron;padding:3px 8px">' + T(L[0], L[1]) + '</button>';
  });
  layerBtns += '</div>';
  return '<figure class="nc-map-wrap"><div class="nc-map-stage ' + (themed ? 'theme-map' : '') + '"><img class="nc-map-image" src="/maps/night-city-v04-nightcityio.jpg" alt="' + T('Night City Map', 'Карта Найт-Сити') + '"><div class="nc-map-tint" aria-hidden="true"></div>' + layerBtns + '<button class="nc-map-palette" type="button" data-map-palette>' + (themed ? T('THEME MAP', 'ЦВЕТА ТЕМЫ') : T('ORIGINAL MAP', 'ОРИГИНАЛ')) + '</button><svg class="nc-map-overlay" viewBox="0 0 1000 1000" role="group"><defs><filter id="mapGlow"><feGaussianBlur stdDeviation="3" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>' + contractMarkers + poiMarkers + vendorMarkers + '</svg></div><figcaption class="small muted nc-map-source">' + T('NightCity.io v0.04 · layered overlay by NC//NET', 'NightCity.io v0.04 · слоистый оверлей NC//NET') + '</figcaption></figure>';
}

function ncBindLayerToggles(root) {
  $$('.nc-layer-btn', root).forEach(function(btn) {
    btn.onclick = function() {
      var key = btn.dataset.layer;
      NC_MAP_LAYERS[key] = !NC_MAP_LAYERS[key];
      $$('.nc-layer-btn', root).forEach(function(b) {
        if (b.dataset.layer === key) b.classList.toggle('active', NC_MAP_LAYERS[key]);
      });
      $$('.nc-layer-' + key, root).forEach(function(el) {
        el.style.display = NC_MAP_LAYERS[key] ? '' : 'none';
      });
    };
  });
}

function ncMapHtml(contracts){
  const markers=contracts.map((contract,index)=>{const anchor=NC_MAP_COORDS[contract.district_id]||[535,470],jitter=((contract.id*37)%46)-23,jitterY=((contract.id*19)%38)-19,x=Math.max(28,Math.min(972,anchor[0]+jitter)),y=Math.max(28,Math.min(972,anchor[1]+jitterY));return `<g class="nc-marker" data-contract-open="${contract.id}" role="button" tabindex="0" aria-label="${esc(T('Open Contract: ','Открыть Contract: ')+contract.title)}" transform="translate(${x} ${y})" filter="url(#mapGlow)"><circle class="pulse" r="17"></circle><circle r="11"></circle><text y="4" text-anchor="middle">${index+1}</text><title>${esc(contract.title)}</title></g>`;}).join('');
  const themed=ncMapThemeMode();return `<figure class="nc-map-wrap"><div class="nc-map-stage ${themed?'theme-map':''}"><img class="nc-map-image" src="/maps/night-city-v04-nightcityio.jpg" alt="${T('Detailed district map of Night City','Подробная карта районов Найт-Сити')}"><div class="nc-map-tint" aria-hidden="true"></div><button class="nc-map-palette" type="button" data-map-palette aria-pressed="${themed?'true':'false'}">${themed?T('THEME MAP','ЦВЕТА ТЕМЫ'):T('ORIGINAL MAP','ОРИГИНАЛ')}</button><svg class="nc-map-overlay" viewBox="0 0 1000 1000" role="group" aria-label="${T('Active Contract markers','Маркеры активных Contracts')}"><defs><filter id="mapGlow"><feGaussianBlur stdDeviation="3" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>${markers}</svg></div><figcaption class="small muted nc-map-source">${T('NightCity.io v0.04 district artwork · supplied by the campaign owner · interactive Contract overlay by NC//NET','Карта районов NightCity.io v0.04 · предоставлена владельцем кампании · интерактивный слой Contracts — NC//NET')} · <a href="https://nightcity.io/" target="_blank" rel="noopener">NightCity.io ↗</a></figcaption></figure>`;
}

async function viewContracts(view){
  view.innerHTML=spinner();const data=await api('/api/contracts');let contracts=data.contracts;
  view.innerHTML=`<div class="page-head"><div><h1>🎯 ${T('Contracts','Контракты')}</h1><div class="sub">NC//NET CRIME RELAY · ${contracts.length} ${T('signals','сигналов')}</div></div><a class="btn-sm" href="/api/calendar.ics" download>📅 iCal</a>${state.me?.is_gm?`<button class="btn-primary" id="nc-contract-new">＋ ${T('New Contract','Новый контракт')}</button>`:''}</div><div class="nc-contract-layout"><aside class="panel nc-map-filters"><h3>${T('Location Filter','Фильтр локаций')}</h3><button class="active" data-contract-district="">${T('All Night City','Весь Найт-Сити')}</button>${ncDistrictFilters()}</aside><section id="nc-contract-map">${ncMapHtml(contracts)}</section><section class="nc-contract-list" id="nc-contract-list">${contracts.length?contracts.map(ncContractCard).join(''):`<div class="empty">${T('No active Contract signals.','Нет активных сигналов Contracts.')}</div>`}</section></div>`;
  const bind=()=>{ncBindActivation('[data-contract-open]',view,element=>go(`/contracts/${element.dataset.contractOpen}`));ncBindMapControls(view);};bind();
  $$('[data-contract-district]',view).forEach(btn=>btn.onclick=()=>{const id=btn.dataset.contractDistrict;$$('[data-contract-district]',view).forEach(x=>x.classList.toggle('active',x===btn));const filtered=contracts.filter(contract=>ncLocationMatches(id,contract.district_id));$('#nc-contract-map').innerHTML=ncMapHtml(filtered);$('#nc-contract-list').innerHTML=filtered.length?filtered.map(ncContractCard).join(''):`<div class="empty">${T('No signals in this location.','В этой локации нет сигналов.')}</div>`;bind();NC_AUDIO.tone(620,.04);});
  if($('#nc-contract-new'))$('#nc-contract-new').onclick=()=>openContractEditor();
}

function contractEditorBody(modal,coverMediaId){const mode=$('#ct-reward-mode',modal).value,rawMax=$('#ct-reward-max',modal).value,time=$('#ct-time',modal).value;const personaId=Number($('#ct-persona',modal).value)||null;return {title:$('#ct-title',modal).value,status:$('#ct-status',modal).value,storyline_id:Number($('#ct-story',modal).value)||null,district_id:$('#ct-district',modal).value,risk_level:$('#ct-risk',modal).value,scheduled_at:time?new Date(time).getTime()/1000:null,crew_capacity:Number($('#ct-capacity',modal).value)||0,reward_mode:mode,reward_exact:mode==='exact'?Number($('#ct-reward-min',modal).value)||0:null,reward_min:mode==='range'?Number($('#ct-reward-min',modal).value)||0:null,reward_max:mode==='range'?Number(rawMax)||0:null,reward_text:mode==='negotiable'?rawMax:'',service_format:$('#ct-format',modal).value,teaser:$('#ct-teaser',modal).value,public_brief:$('#ct-public',modal).value,classified_brief:$('#ct-classified',modal).value,service_contact:$('#ct-contact',modal).value,service_vtt_url:$('#ct-vtt',modal).value,requirements:$('#ct-requirements',modal).value,content_notes:$('#ct-content-notes',modal).value,service_notes:$('#ct-service-notes',modal).value,cover_media_id:coverMediaId,participants:[...(personaId?[{persona_id:personaId,role_key:'poster',role_label:'Fixer',visibility:'public'}]:[]),...$$('[data-participant-row]',modal).map(row=>({persona_id:Number($('[data-p-persona]',row).value),role_key:$('[data-p-role]',row).value,role_label:$('[data-p-role]',row).value,visibility:$('[data-p-visibility]',row).value,note:$('[data-p-note]',row).value}))]};}
function openContractPreviewModal(contract,onPublish){const poster=contract.participants?.find(item=>item.role_key==='poster')||contract.participants?.[0];const modal=openModal(`<h2>${T('Contract Preview','Предпросмотр Contract')}</h2>${previewBanner()}<div class="mb">${ncContractCard(contract)}</div><div class="panel"><div class="kv"><b>${T('Risk','Риск')}</b><span>${esc(ncLabel(contract.risk_level).toUpperCase())}</span><b>${T('Reward','Награда')}</b><span>${esc(ncReward(contract))}</span><b>${T('Crew','Команда')}</b><span>${contract.crew_capacity?`0/${contract.crew_capacity}`:T('open crew','без лимита')}</span><b>${T('Format','Формат')}</b><span class="user-content">${esc(contract.service_format||'—')}</span></div></div><div class="panel mt"><h3>${T('Public Briefing','Публичный брифинг')}</h3><div class="desc user-content" style="white-space:pre-wrap">${esc(contract.public_brief||contract.teaser||'—')}</div>${contract.requirements?`<h4>${T('Operator Requirements','Требования к операторам')}</h4><div class="user-content">${esc(contract.requirements)}</div>`:''}${contract.content_notes?`<h4>${T('Content Notes','Предупреждения')}</h4><div class="user-content">${esc(contract.content_notes)}</div>`:''}</div><div class="panel mt classified-panel"><h3>🔐 ${T('Classified Package','Закрытый пакет')}</h3><div class="desc user-content" style="white-space:pre-wrap">${esc(contract.classified_brief||T('No additional data.','Дополнительных данных нет.'))}</div>${contract.participants?.length?`<h4>${T('Participants','Участники')}</h4>${contract.participants.map(p=>`<div class="inv-row"><span class="iname user-content">${esc(p.display_name||p.handle)}</span><span class="tag">${esc(p.visibility||'public')} · ${esc(p.role_key||'custom')}</span></div>`).join('')}`:''}</div><div class="row mt"><button id="cpv-back">← ${T('Back to Edit','Назад к редактированию')}</button><button class="btn-primary" id="cpv-save">${T('Transmit Contract','Передать Contract')}</button></div>`,true);$('#cpv-back',modal).onclick=()=>closeModal();$('#cpv-save',modal).onclick=()=>{closeModal(true);onPublish();};}

async function openContractEditor(existing){
  const [personaData,storyData]=await Promise.all([api('/api/personas?manage=1'),api('/api/storylines')]);const contract=existing||{};let coverMediaId=contract.cover_media_id||null;
  const poster=contract.participants?.find(item=>item.role_key==='poster');let participantDraft=(contract.participants||[]).filter(item=>item.id!==poster?.id).map(item=>({...item}));
  const modal=openModal(`<h2>${existing?T('Edit Contract','Изменить контракт'):T('New Contract Signal','Новый сигнал Contract')}</h2><div class="grid cols-2"><label class="f"><span>${T('Title','Название')}</span><input id="ct-title" maxlength="180" value="${esc(contract.title||'')}"></label><label class="f"><span>${T('Status','Статус')}</span><select id="ct-status">${['draft','open','crew_full','in_progress','completed','failed','cancelled','archived'].map(v=>`<option ${contract.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="f"><span>${T('Posting Persona','Размещающая Persona')}</span><select id="ct-persona"><option value="">—</option>${personaData.personas.map(p=>`<option value="${p.id}" ${poster?.persona_id===p.id?'selected':''}>${esc(p.display_name)} · @${esc(p.handle)}</option>`).join('')}</select></label><label class="f"><span>${T('Storyline','Сюжетная линия')}</span><select id="ct-story"><option value="">—</option>${storyData.storylines.filter(s=>s.can_edit).map(s=>`<option value="${s.id}" ${contract.storyline_id===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select></label><label class="f"><span>${T('District','Район')}</span><select id="ct-district">${ncLocationOptions(contract.district_id,T('Classified','Секретно'))}</select></label><label class="f"><span>${T('Risk','Риск')}</span><select id="ct-risk">${['low','moderate','high','extreme','classified'].map(v=>`<option ${contract.risk_level===v?'selected':''}>${v}</option>`).join('')}</select><label class="f"><span>${T('Connection Window','Окно подключения')}</span><input id="ct-time" type="datetime-local" value="${contract.scheduled_at?new Date(contract.scheduled_at*1000-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):''}"></label><label class="f"><span>${T('Crew Capacity','Размер команды')}</span><input id="ct-capacity" type="number" min="0" max="100" value="${contract.crew_capacity??4}"></label><label class="f"><span>${T('Reward Mode','Режим награды')}</span><select id="ct-reward-mode">${['exact','range','negotiable','hidden'].map(v=>`<option ${contract.reward_mode===v?'selected':''}>${v}</option>`).join('')}</select><label class="f"><span>${T('Reward / Min','Награда / минимум')}</span><input id="ct-reward-min" type="number" value="${contract.reward_exact??contract.reward_min??''}"></label><label class="f"><span>${T('Reward Max / Text','Максимум / текст')}</span><input id="ct-reward-max" value="${esc(contract.reward_max??contract.reward_text??'')}"></label><label class="f"><span>${T('Session Format','Формат сессии')}</span><input id="ct-format" value="${esc(contract.service_format||'Cyberpunk RED / CEMK')}"></label></div><div class="panel mb"><div class="row" style="justify-content:space-between"><h3>${T('Additional Participants','Дополнительные участники')}</h3><button id="ct-participant-add">＋</button></div><div id="ct-participants"></div></div><label class="f"><span>${T('Teaser','Тизер')}</span><textarea id="ct-teaser">${esc(contract.teaser||'')}</textarea></label><label class="f"><span>${T('Public Briefing','Публичный брифинг')}</span><textarea id="ct-public" style="min-height:150px">${esc(contract.public_brief||'')}</textarea></label><label class="f"><span>${T('Classified Briefing','Закрытый брифинг')}</span><textarea id="ct-classified" style="min-height:150px">${esc(contract.classified_brief||'')}</textarea></label><div class="grid cols-2"><label class="f"><span>${T('Service Contact','Служебный контакт')}</span><input id="ct-contact" value="${esc(contract.service_contact||'')}"></label><label class="f"><span>Discord / VTT</span><input id="ct-vtt" value="${esc(contract.service_vtt_url||'')}"></label></div><label class="f"><span>${T('Operator Requirements','Требования к операторам')}</span><textarea id="ct-requirements">${esc(contract.requirements||'')}</textarea></label><label class="f"><span>${T('Content Notes','Предупреждения о содержании')}</span><textarea id="ct-content-notes">${esc(contract.content_notes||'')}</textarea></label><label class="f"><span>${T('Classified Service Notes','Закрытые служебные заметки')}</span><textarea id="ct-service-notes">${esc(contract.service_notes||'')}</textarea></label><div class="row"><label class="btn-sm">${T('Contract Image (optional)','Изображение Contract (необязательно)')}<input id="ct-cover-file" type="file" accept="image/jpeg,image/png,image/webp" hidden></label>${coverMediaId?`<button id="ct-cover-remove">${T('Remove Image','Удалить изображение')}</button>`:''}<span id="ct-cover-status" class="small muted">${coverMediaId?T('Image attached','Изображение прикреплено'):T('No image — allowed','Изображения нет — это допустимо')}</span><button id="ct-cancel">${T('Cancel','Отмена')}</button><button class="btn-sm" id="ct-preview">${T('Preview','Предпросмотр')}</button><button class="btn-primary" id="ct-save">${T('Transmit Contract','Передать Contract')}</button></div>`,true);
  const renderParticipants=()=>{$('#ct-participants',modal).innerHTML=participantDraft.map((item,index)=>`<div class="row mb" data-participant-row="${index}"><select data-p-persona>${personaData.personas.map(p=>`<option value="${p.id}" ${item.persona_id===p.id?'selected':''}>${esc(p.display_name)}</option>`).join('')}</select><select data-p-role>${['client','broker','contact','target','informant','custom'].map(role=>`<option ${item.role_key===role?'selected':''}>${role}</option>`).join('')}</select><select data-p-visibility><option ${item.visibility==='public'?'selected':''}>public</option><option ${item.visibility==='classified'?'selected':''}>classified</option></select><input data-p-note placeholder="${T('Participant note','Заметка участника')}" value="${esc(item.note||'')}"><button data-p-remove="${index}">✕</button></div>`).join('');$$('[data-p-remove]',modal).forEach(btn=>btn.onclick=()=>{participantDraft.splice(Number(btn.dataset.pRemove),1);renderParticipants();});};renderParticipants();$('#ct-participant-add',modal).onclick=()=>{if(!personaData.personas.length)return;participantDraft.push({persona_id:personaData.personas[0].id,role_key:'custom',visibility:'public',note:''});renderParticipants();};$('#ct-cover-file',modal).onchange=()=>openImageCrop($('#ct-cover-file',modal).files[0],'contract_image',media=>{coverMediaId=media.id;$('#ct-cover-status',modal).textContent=`${T('Image ready','Изображение готово')}: ${media.width}×${media.height}px`;toast(T('Contract image ready.','Изображение Contract готово.'));});if($('#ct-cover-remove',modal))$('#ct-cover-remove',modal).onclick=()=>{coverMediaId=null;$('#ct-cover-status',modal).textContent=T('Image will be removed.','Изображение будет удалено.');$('#ct-cover-remove',modal).disabled=true;};$('#ct-cancel',modal).onclick=closeModal;const publish=async()=>{try{await api(existing?`/api/contracts/${existing.id}`:'/api/contracts',{method:existing?'PUT':'POST',body:contractEditorBody(modal,coverMediaId)});closeModal(true);toast(T('Contract transmitted.','Contract передан.'));route();NC_AUDIO.tone(980,.12);}catch(e){toast(e.message,true);}};$('#ct-preview',modal).onclick=async()=>{try{const preview=await api('/api/contracts/preview',{method:'POST',body:contractEditorBody(modal,coverMediaId)});openContractPreviewModal(preview,publish);}catch(e){toast(e.message,true);}};$('#ct-save',modal).onclick=publish
}

async function viewContractDetail(view,id){
  view.innerHTML=spinner();const contract=await api(`/api/contracts/${id}`);const poster=contract.participants?.find(p=>p.role_key==='poster')||contract.participants?.[0];const canPublishAftermath=!contract.aftermath_published&&['open','crew_full','in_progress','completed','failed'].includes(contract.status);
  view.innerHTML=`<div class="page-head"><div><div class="small muted">NC//NET CONTRACT #${contract.id}</div><h1 class="user-content">${esc(contract.title)}</h1><div class="sub"><span class="tag">${esc(ncLabel(contract.status).toUpperCase())}</span> · ${esc(ncDistrictName(contract.district_id))} · ${esc(ncDate(contract.scheduled_at))}</div></div><div class="row"><button onclick="location.hash='#/contracts'">← ${T('Contracts','Контракты')}</button>${contract.can_edit?`<button id="ct-edit">✏️ ${T('Edit','Изменить')}</button><button id="ct-session">▶ ${contract.active_session_id?T('Open Session','Открыть сессию'):T('New Session','Новая сессия')}</button>${canPublishAftermath?`<button id="ct-aftermath">◈ ${T('Aftermath','Последствия')}</button>`:''}`:''}</div></div>${contract.cover_media_id?`<div class="nc-contract-detail-cover-frame"><img class="nc-contract-detail-cover" src="/api/media/${esc(contract.cover_media_id)}" alt="${esc(contract.title)}"></div>`:''}<div class="grid cols-2"><section><div class="panel accent"><div class="row">${ncAuthorAvatar(poster)}<div><b class="user-content">${esc(poster?.display_name||'NC//NET')}</b><div class="small muted">${esc(poster?.role_label||T('Contract Relay','Канал Contract'))}</div></div></div></div><div class="panel mt"><h2>${T('Public Briefing','Публичный брифинг')}</h2><div class="desc user-content" style="white-space:pre-wrap">${esc(contract.public_brief||contract.teaser)}</div>${contract.requirements?`<h3>${T('Operator Requirements','Требования к операторам')}</h3><div class="user-content">${esc(contract.requirements)}</div>`:''}${contract.content_notes?`<h3>${T('Content Notes','Предупреждения')}</h3><div class="user-content">${esc(contract.content_notes)}</div>`:''}</div>${contract.has_classified_access?`<div class="panel mt classified-panel"><h2>🔐 ${T('Classified Package','Закрытый пакет')}</h2><div class="desc user-content" style="white-space:pre-wrap">${esc(contract.classified_brief||T('No additional data.','Дополнительных данных нет.'))}</div>${contract.service_contact?`<p class="user-content"><b>CONTACT:</b> ${esc(contract.service_contact)}</p>`:''}${contract.service_vtt_url?`<p><a href="${esc(contract.service_vtt_url)}" target="_blank" rel="noopener">DISCORD / VTT ↗</a></p>`:''}${contract.service_notes?`<div class="user-content">${esc(contract.service_notes)}</div>`:''}</div>`:`<div class="panel mt locked-panel">🔒 ${T('Classified briefing unlocks for the active Crew.','Закрытый брифинг откроется основному составу Crew.')}</div>`}</section><aside><div class="panel"><div class="kv"><b>${T('Risk','Риск')}</b><span>${esc(ncLabel(contract.risk_level).toUpperCase())}</span><b>${T('Reward','Награда')}</b><span>${esc(ncReward(contract))}</span><b>${T('Crew','Команда')}</b><span>${contract.crew_count}/${contract.crew_capacity||'∞'}</span><b>${T('Waitlist','Резерв')}</b><span>${contract.waitlist_count}</span><b>${T('Format','Формат')}</b><span class="user-content">${esc(contract.service_format||'—')}</span>${contract.gm_display_name?`<b>${T('Service GM','Служебный GM')}</b><span class="user-content">${esc(contract.gm_display_name)}</span>`:''}</div></div><div class="panel mt"><h3>${T('Crew Manifest','Состав команды')}</h3>${contract.signups.length?contract.signups.map(s=>`<div class="inv-row"><span class="iname user-content">${esc(s.character_name)}</span><span class="tag">${esc(ncLabel(s.status))}</span></div>`).join(''):`<div class="empty">${T('No operators connected.','Операторы не подключены.')}</div>`}<div id="ct-actions" class="mt"></div></div></aside></div>`;
  const contractImage=$('.nc-contract-detail-cover',view);if(contractImage){contractImage.setAttribute('role','button');contractImage.setAttribute('tabindex','0');contractImage.setAttribute('aria-label',T('Open full-size Contract image','Открыть изображение Contract в полном размере'));const openContractImage=()=>openModal(`<h2>${esc(contract.title)}</h2><div class="feed-image-lightbox"><img src="${contractImage.src}" alt="${esc(contract.title)}"></div>`,true);contractImage.onclick=openContractImage;contractImage.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openContractImage();}};}
  if(contract.can_edit){$('#ct-edit').onclick=()=>openContractEditor(contract);if($('#ct-aftermath'))$('#ct-aftermath').onclick=()=>openAftermath(contract);$('#ct-session').onclick=async()=>{try{if(contract.active_session_id){openSessionDashboard(contract.active_session_id);return;}const session=await api('/api/sessions',{method:'POST',body:{contract_id:contract.id,title:contract.title}});openSessionDashboard(session.id);}catch(e){toast(e.message,true);}};}
  const actions=$('#ct-actions'),activeContract=['open','crew_full','in_progress'].includes(contract.status);
  if(state.me&&!contract.can_edit&&activeContract){
    const mySignups=contract.my_signups||[];
    let chars=[];try{chars=(await api('/api/characters')).characters.filter(c=>!c.data.archived&&!mySignups.some(signup=>signup.character_id===c.id));}catch(e){}
    const connected=mySignups.map(signup=>`<div class="inv-row"><span class="iname user-content">${esc(signup.character_name)}</span><span class="tag">${esc(ncLabel(signup.status))}</span><button class="btn-danger" data-ct-leave="${signup.id}">${T('Disconnect','Отключить')}</button></div>`).join('');
    const join=chars.length?`<label class="f"><span>${T('Operator Dossier','Досье оператора')}</span><select id="ct-char">${chars.map(c=>`<option value="${c.id}">${esc(c.data.handle)}</option>`).join('')}</select></label><button class="btn-primary" id="ct-join">${T('REQUEST ACCESS','ЗАПРОСИТЬ ДОСТУП')}</button>`:(!mySignups.length?`<a class="btn-primary" href="#/dossiers">${T('Create a Dossier first','Сначала создайте досье')}</a>`:'');
    actions.innerHTML=connected+join;
    $$('[data-ct-leave]',actions).forEach(button=>button.onclick=async()=>{try{await api(`/api/contracts/${contract.id}/leave`,{method:'POST',body:{signup_id:Number(button.dataset.ctLeave)}});route();}catch(e){toast(e.message,true);}});
    if($('#ct-join'))$('#ct-join').onclick=async()=>{try{await api(`/api/contracts/${contract.id}/join`,{method:'POST',body:{character_id:Number($('#ct-char').value)}});route();NC_AUDIO.tone(1040,.12);}catch(e){toast(e.message,true);}};
  }
  if(contract.active_session_id&&contract.has_classified_access)actions.insertAdjacentHTML('beforeend',`<a class="btn-primary mt" href="#/session/${contract.active_session_id}">▶ ${T('LIVE SESSION VIEW','ЭКРАН АКТИВНОЙ СЕССИИ')}</a>`);
}

async function openAftermath(contract){const personas=(await api('/api/personas?manage=1')).personas;const crew=contract.signups.filter(s=>s.status==='crew'&&s.character_id);const modal=openModal(`<h2>${T('Contract Aftermath','Последствия Contract')}</h2><label class="f"><span>${T('Result','Результат')}</span><select id="af-result"><option>completed</option><option>failed</option></select></label><label class="f"><span>${T('Publishing Persona','Публикующая Persona')}</span><select id="af-persona">${personas.map(p=>`<option value="${p.id}">${esc(p.display_name)}</option>`).join('')}</select></label><label class="f"><span>${T('Headline','Заголовок')}</span><input id="af-headline" value="${esc('Aftermath: '+contract.title)}"></label><label class="f"><span>${T('City Feed Report','Материал City Feed')}</span><textarea id="af-body" style="min-height:140px"></textarea></label><h3>${T('Crew Rewards','Награды Crew')}</h3>${crew.map(s=>`<div class="row af-reward" data-character="${s.character_id}"><b class="user-content">${esc(s.character_name)}</b><label>€$ <input data-reward-cash type="number" value="0"></label><label>IP <input data-reward-ip type="number" value="0"></label></div>`).join('')}<button class="btn-primary mt" id="af-publish">${T('Complete Contract and Publish','Завершить Contract и опубликовать')}</button>`,true);$('#af-publish',modal).onclick=async()=>{const rewards=$$('.af-reward',modal).map(row=>({character_id:Number(row.dataset.character),cash:Number($('[data-reward-cash]',row).value)||0,ip:Number($('[data-reward-ip]',row).value)||0}));try{const result=await api(`/api/contracts/${contract.id}/aftermath`,{method:'POST',body:{result:$('#af-result',modal).value,author_persona_id:Number($('#af-persona',modal).value),headline:$('#af-headline',modal).value,body:$('#af-body',modal).value,rewards}});closeModal();go(`/feed/${result.post_id}`);}catch(e){toast(e.message,true);}};}

function ncFeedCard(post){return `<article class="nc-feed-card format-${esc(post.format)}" data-feed-open="${post.id}" role="button" tabindex="0" aria-label="${esc(T('Open Transmission: ','Открыть передачу: ')+(post.headline||post.body.slice(0,80)))}" style="--persona:${esc(post.author?.accent_color||'#ff2d78')}"><header>${ncAuthorAvatar(post.author)}<div><b class="user-content">${esc(post.author?.display_name||'Unknown')}</b><div class="small muted">${esc(ncLabel(post.format).toUpperCase())} · ${post.district_id?esc(ncDistrictName(post.district_id))+' · ':''}${timeAgo(post.published_at||post.created)}</div></div></header>${post.image_media_id?`<div class="nc-feed-image-frame"><img class="nc-feed-image" src="/api/media/${esc(post.image_media_id)}" alt="${esc(post.headline||T('City Feed image','Изображение City Feed'))}" loading="lazy"></div>`:''}${post.headline?`<h2 class="user-content">${esc(post.headline)}</h2>`:''}${post.lead?`<p class="lead user-content">${esc(post.lead)}</p>`:''}${post.truth_status?`<div class="gm-truth-strip">GM TRUTH // ${esc(post.truth_status.replaceAll('_',' ').toUpperCase())}</div>`:''}${post.status!=='published'?`<div class="tag">${esc(ncLabel(post.status).toUpperCase())}</div>`:''}<div class="desc user-content">${esc(post.body)}</div></article>`;}

async function viewCityFeed(view){
  view.innerHTML=spinner();const data=await api('/api/feed');view.innerHTML=`<div class="page-head"><div><h1>📡 ${T('City Feed','Городская лента')}</h1><div class="sub">NC//NET LIVE TRANSMISSIONS · ${data.posts.length}</div></div>${state.me?`<button class="btn-primary" id="feed-compose">＋ ${T('Transmit','Передать')}</button>`:''}</div><div class="nc-feed-layout"><main id="feed-stream">${data.posts.length?data.posts.map(ncFeedCard).join(''):`<div class="empty">${T('The city is quiet. For now.','Город молчит. Пока что.')}</div>`}</main><aside class="panel"><h3>${T('Channels','Каналы')}</h3><button class="btn-sm active" data-feed-filter="">${T('ALL SIGNALS','ВСЕ СИГНАЛЫ')}</button><hr><p class="small muted">${T('Character transmissions publish immediately. GM moderation happens only after publication.','Передачи Characters публикуются сразу. GM модерирует только уже опубликованный материал.')}</p></aside></div>`;
  const bind=()=>ncBindActivation('[data-feed-open]',view,card=>go(`/feed/${card.dataset.feedOpen}`));bind();
  $$('[data-feed-filter]',view).forEach(button=>button.onclick=()=>{const f=button.dataset.feedFilter;const posts=f?data.posts.filter(p=>p.format===f):data.posts;$('#feed-stream').innerHTML=posts.map(ncFeedCard).join('')||`<div class="empty">${T('No transmissions.','Нет передач.')}</div>`;bind();});if($('#feed-compose'))$('#feed-compose').onclick=()=>openFeedComposer();
}

async function ncAvailableAuthors(){let chars=[],personas=[];try{chars=(await api('/api/characters')).characters;}catch(e){}if(state.me?.is_gm)try{personas=(await api('/api/personas?manage=1')).personas;}catch(e){}return [...chars.map(c=>({value:`character:${c.id}`,label:c.data.handle})),...personas.map(p=>({value:`persona:${p.id}`,label:`${p.display_name} · @${p.handle}`}))];}
function feedComposerBody(modal,imageMediaId,replyTo){const [kind,id]=$('#fp-author',modal).value.split(':'),event=$('#fp-event',modal).value;const body={format:'article',headline:$('#fp-headline',modal).value,body:$('#fp-body',modal).value,district_id:$('#fp-district',modal).value,event_at:event?new Date(event).getTime()/1000:null,reply_to_post_id:replyTo||null,image_media_id:imageMediaId,truth_status:$('#fp-truth',modal)?.value||'unknown'};body[kind==='persona'?'author_persona_id':'author_character_id']=Number(id);return body;}
function previewBanner(){return `<div class="panel accent mb"><b>👁 ${T('PREVIEW — NOT PUBLISHED','ПРЕДПРОСМОТР — НЕ ОПУБЛИКОВАНО')}</b><p class="small">${T('This is a preview. Publishing will still re-validate the content.','Это предпросмотр. Публикация повторно проверит содержимое.')}</p></div>`;}
function openFeedPreviewModal(post,onPublish){const modal=openModal(`<h2>${T('Feed Preview','Предпросмотр публикации')}</h2>${previewBanner()}<div class="table-scroll">${ncFeedCard(post)}</div><div class="row mt"><button id="fpv-back">← ${T('Back to Edit','Назад к редактированию')}</button><button class="btn-primary" id="fpv-publish">${T('PUBLISH NOW','ОПУБЛИКОВАТЬ СЕЙЧАС')}</button></div>`,true);$('#fpv-back',modal).onclick=()=>closeModal();$('#fpv-publish',modal).onclick=()=>{closeModal(true);onPublish();};}

async function openFeedComposer(replyTo){const authors=await ncAvailableAuthors();let imageMediaId=null;if(!authors.length){toast(T('Create a Character Dossier first.','Сначала создайте Character Dossier.'),true);return;}const modal=openModal(`<h2>${T('New Transmission','Новая передача')}</h2><div class="grid cols-2"><label class="f"><span>${T('Author','Автор')}</span><select id="fp-author">${authors.map(a=>`<option value="${a.value}">${esc(a.label)}</option>`).join('')}</select></label><label class="f"><span>${T('District','Район')}</span><select id="fp-district">${ncLocationOptions('')}</select></label><label class="f"><span>${T('Event Time','Время события')}</span><input id="fp-event" type="datetime-local"></label>${state.me?.is_gm?`<label class="f"><span>${T('GM Truth Status','Статус истины GM')}</span><select id="fp-truth">${['unknown','true','partially_true','false','propaganda'].map(value=>`<option value="${value}">${value}</option>`).join('')}</select></label>`:''}</div><label class="f"><span>${T('Headline (optional)','Заголовок (необязательно)')}</span><input id="fp-headline" maxlength="240"></label><label class="f"><span>${T('Transmission','Передача')}</span><textarea id="fp-body" maxlength="30000" style="min-height:180px"></textarea></label><div class="row"><label class="btn-sm">${T('Attach Image (optional)','Добавить изображение (необязательно)')}<input id="fp-image-file" type="file" accept="image/jpeg,image/png,image/webp" hidden></label><span id="fp-image-status" class="small muted">${T('No image — publication is allowed','Изображения нет — публикация разрешена')}</span><button id="fp-cancel">${T('Cancel','Отмена')}</button><button class="btn-sm" id="fp-preview">${T('Preview','Предпросмотр')}</button><button class="btn-primary" id="fp-send">${T('PUBLISH NOW','ОПУБЛИКОВАТЬ СЕЙЧАС')}</button></div>`,true);$('#fp-image-file',modal).onchange=()=>openImageCrop($('#fp-image-file',modal).files[0],'feed_image',media=>{imageMediaId=media.id;$('#fp-image-status',modal).textContent=`${T('Image ready','Изображение готово')}: ${media.width}×${media.height}px`;toast(T('Image ready.','Изображение готово.'));});$('#fp-cancel',modal).onclick=closeModal;const publish=async()=>{try{const post=await api('/api/feed',{method:'POST',body:feedComposerBody(modal,imageMediaId,replyTo)});closeModal(true);go(`/feed/${post.id}`);NC_AUDIO.tone(1240,.16,'sawtooth');}catch(e){toast(e.message,true);}};$('#fp-preview',modal).onclick=async()=>{try{const preview=await api('/api/feed/preview',{method:'POST',body:feedComposerBody(modal,imageMediaId,replyTo)});openFeedPreviewModal(preview,publish);}catch(e){toast(e.message,true);}};$('#fp-send',modal).onclick=publish}

async function viewFeedDetail(view,id){
  view.innerHTML=spinner();
  const post=await api(`/api/feed/${id}`);
  const revisionValue=value=>value==null?'—':(typeof value==='object'?JSON.stringify(value):String(value));
  const comments=(post.comments||[]).map(comment=>`<div class="nc-comment ${comment.parent_comment_id?'reply':''} ${comment.hidden?'hidden-comment':''}" data-comment="${comment.id}">${ncAuthorAvatar(comment.author)}<div><b class="user-content">${esc(comment.author?.display_name||'?')}</b><span class="small muted"> · ${timeAgo(comment.created)}</span>${comment.hidden?` <span class="tag">${T('HIDDEN','СКРЫТ')}</span>`:''}<div class="user-content">${esc(comment.body)}</div>${comment.hidden_reason?`<div class="small warn-text">${T('Moderation reason','Причина модерации')}: ${esc(comment.hidden_reason)}</div>`:''}<div class="row">${state.me&&!comment.hidden?`<button class="btn-sm" data-comment-reply="${comment.id}">${T('Reply','Ответить')}</button>`:''}${state.me?.is_gm&&!comment.hidden?`<button class="btn-sm btn-danger" data-comment-hide="${comment.id}">${T('Hide','Скрыть')}</button>`:''}</div></div></div>`).join('');
  const revisions=(post.revisions||[]).map(revision=>`<div class="feed-revision"><div><b>${esc(revision.action.toUpperCase())}</b><span class="small muted user-content"> ${esc(revision.actor)} · ${timeAgo(revision.created)}</span></div><div class="session-change-list">${(revision.changes||[]).map(change=>`<span><b>${esc(change.field.replaceAll('_',' '))}</b> ${esc(revisionValue(change.before))} → ${esc(revisionValue(change.after))}</span>`).join('')||`<span>${T('Recorded','Записано')}</span>`}</div>${revision.reason?`<div class="small user-content">${esc(revision.reason)}</div>`:''}</div>`).join('');
  view.innerHTML=`<div class="page-head"><div><h1>${T('Transmission','Передача')} #${post.id}</h1><div class="sub">${T('Event','Событие')}: ${esc(ncDate(post.event_at))} · ${T('Published','Опубликовано')}: ${esc(ncDate(post.published_at))}</div></div><div class="row"><button onclick="location.hash='#/feed'">← ${T('City Feed','Городская лента')}</button>${post.can_edit?`<button id="feed-edit">✏️ ${T('Edit','Изменить')}</button>`:''}${state.me?.is_gm&&post.status==='published'?`<button class="btn-danger" id="feed-hide">${T('Hide','Скрыть')}</button>`:''}</div></div>${state.me?.is_gm?`<div class="panel classified-panel mb"><div class="row"><b>GM TRUTH</b><select id="feed-truth-status">${['unknown','true','partially_true','false','propaganda'].map(value=>`<option value="${value}" ${post.truth_status===value?'selected':''}>${value}</option>`).join('')}</select><button id="feed-truth-save">${T('Classify','Классифицировать')}</button></div>${post.hidden_reason?`<p class="warn-text">${T('Hidden reason','Причина скрытия')}: ${esc(post.hidden_reason)}</p>`:''}</div>`:''}<div class="nc-feed-detail">${ncFeedCard(post)}<section class="panel"><div class="row" style="justify-content:space-between"><h2>${T('Comments','Комментарии')} · ${(post.comments||[]).length}</h2>${state.me&&post.status==='published'?`<button id="feed-comment-new">＋ ${T('Reply','Ответить')}</button>`:''}</div><div id="feed-comments">${comments||`<div class="empty">${T('No comments yet.','Комментариев пока нет.')}</div>`}</div></section>${revisions?`<details class="panel mt"><summary>${T('Revision History','История изменений')} · ${post.revisions.length}</summary><div class="mt">${revisions}</div></details>`:''}</div>`;
  $$('[data-feed-open]',view).forEach(element=>{element.removeAttribute('data-feed-open');element.removeAttribute('role');element.removeAttribute('tabindex');element.removeAttribute('aria-label');});
  const detailImage=$('.nc-feed-detail .nc-feed-image',view);if(detailImage){detailImage.setAttribute('role','button');detailImage.setAttribute('tabindex','0');detailImage.setAttribute('aria-label',T('Open full-size image','Открыть изображение в полном размере'));const openFullImage=()=>openModal(`<h2>${T('Full-size Image','Полноразмерное изображение')}</h2><div class="feed-image-lightbox"><img src="${detailImage.src}" alt="${esc(post.headline||T('City Feed image','Изображение City Feed'))}"></div>`,true);detailImage.onclick=openFullImage;detailImage.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openFullImage();}};}
  if($('#feed-edit'))$('#feed-edit').onclick=()=>openFeedEditor(post);
  if($('#feed-comment-new'))$('#feed-comment-new').onclick=()=>openCommentComposer(post.id);
  $$('[data-comment-reply]',view).forEach(button=>button.onclick=()=>openCommentComposer(post.id,Number(button.dataset.commentReply)));
  $$('[data-comment-hide]',view).forEach(button=>button.onclick=async()=>{const reason=prompt(T('Reason for hiding this comment','Причина скрытия комментария'));if(!reason)return;try{await api(`/api/feed/${post.id}/comments/${button.dataset.commentHide}/hide`,{method:'POST',body:{reason}});route();}catch(e){toast(e.message,true);}});
  if($('#feed-truth-save'))$('#feed-truth-save').onclick=async()=>{const reason=prompt(T('Optional GM classification note','Необязательная заметка GM'))||'';try{await api(`/api/feed/${post.id}/truth`,{method:'POST',body:{truth_status:$('#feed-truth-status').value,reason}});route();}catch(e){toast(e.message,true);}};
  if($('#feed-hide'))$('#feed-hide').onclick=async()=>{const reason=prompt(T('Reason for hiding this post','Причина скрытия публикации'));if(!reason)return;try{await api(`/api/feed/${post.id}/hide`,{method:'POST',body:{reason}});go('/feed');}catch(e){toast(e.message,true);}};
}

async function openFeedEditor(post){
  let imageMediaId=post.image_media_id||null;
  const modal=openModal(`<h2>${T('Edit Transmission','Изменить передачу')}</h2><div class="grid cols-2"><label class="f"><span>${T('District','Район')}</span><select id="fe-district">${ncLocationOptions(post.district_id)}</select></label><label class="f"><span>${T('Event Time','Время события')}</span><input id="fe-event" type="datetime-local" value="${ncDateTimeInput(post.event_at)}"></label>${state.me?.is_gm?`<label class="f"><span>${T('GM Truth Status','Статус истины GM')}</span><select id="fe-truth">${['unknown','true','partially_true','false','propaganda'].map(value=>`<option value="${value}" ${post.truth_status===value?'selected':''}>${value}</option>`).join('')}</select></label>`:''}</div><label class="f"><span>${T('Headline','Заголовок')}</span><input id="fe-headline" value="${esc(post.headline||'')}"></label><label class="f"><span>${T('Lead','Лид')}</span><textarea id="fe-lead">${esc(post.lead||'')}</textarea></label><label class="f"><span>${T('Body','Текст')}</span><textarea id="fe-body" style="min-height:180px">${esc(post.body)}</textarea></label><div class="row"><label class="btn-sm">${T('Replace Image','Заменить изображение')}<input id="fe-image-file" type="file" accept="image/jpeg,image/png,image/webp" hidden></label>${imageMediaId?`<button id="fe-image-remove">${T('Remove Image','Удалить изображение')}</button>`:''}<span id="fe-image-status" class="small muted">${imageMediaId?T('Image attached','Изображение прикреплено'):T('No image','Нет изображения')}</span></div><div class="row mt"><button id="fe-archive">${T('Archive','В архив')}</button><button class="btn-primary" id="fe-save">${T('Save','Сохранить')}</button></div>`,true);
  $('#fe-image-file',modal).onchange=()=>openImageCrop($('#fe-image-file',modal).files[0],'feed_image',media=>{imageMediaId=media.id;$('#fe-image-status',modal).textContent=T('New image ready','Новое изображение готово');});
  if($('#fe-image-remove',modal))$('#fe-image-remove',modal).onclick=()=>{imageMediaId=null;$('#fe-image-status',modal).textContent=T('Image will be removed','Изображение будет удалено');$('#fe-image-remove',modal).disabled=true;};
  const save=async status=>{const event=$('#fe-event',modal).value;const body={headline:$('#fe-headline',modal).value,lead:$('#fe-lead',modal).value,body:$('#fe-body',modal).value,format:post.format||'article',district_id:$('#fe-district',modal).value,event_at:event?new Date(event).getTime()/1000:null,image_media_id:imageMediaId,status,truth_status:$('#fe-truth',modal)?.value};try{await api(`/api/feed/${post.id}`,{method:'PUT',body});closeModal();route();}catch(e){toast(e.message,true);}};
  $('#fe-save',modal).onclick=()=>save('published');$('#fe-archive',modal).onclick=()=>save('archived');
}

async function openCommentComposer(postId,parentId){const authors=await ncAvailableAuthors();if(!authors.length){toast(T('No available author.','Нет доступного автора.'),true);return;}const modal=openModal(`<h2>${T('Reply to Transmission','Ответить на передачу')}</h2><label class="f"><span>${T('Author','Автор')}</span><select id="fc-author">${authors.map(a=>`<option value="${a.value}">${esc(a.label)}</option>`).join('')}</select></label><label class="f"><span>${T('Comment','Комментарий')}</span><textarea id="fc-body" maxlength="5000"></textarea></label><button class="btn-primary" id="fc-send">${T('Publish Reply','Опубликовать ответ')}</button>`);$('#fc-send',modal).onclick=async()=>{const [kind,id]=$('#fc-author',modal).value.split(':');const body={body:$('#fc-body',modal).value,parent_comment_id:parentId||null};body[kind==='persona'?'author_persona_id':'author_character_id']=Number(id);try{await api(`/api/feed/${postId}/comments`,{method:'POST',body});closeModal();route();}catch(e){toast(e.message,true);}};}

async function viewPersonas(view){view.innerHTML=spinner();const data=await api(`/api/personas${state.me?.is_gm?'?manage=1':''}`);view.innerHTML=`<div class="page-head"><div><h1>◈ ${T('Personas','Персоны')}</h1><div class="sub">${T('Voices, organizations, and identities on NC//NET.','Голоса, организации и личности NC//NET.')}</div></div>${state.me?.is_gm?`<button class="btn-primary" id="persona-new">＋ ${T('New Persona','Новая Persona')}</button>`:''}</div><div class="grid cols-3">${data.personas.map(p=>`<article class="card nc-persona-card" data-persona-open="${p.id}" role="button" tabindex="0" aria-label="${esc(T('Open Persona: ','Открыть Persona: ')+p.display_name)}" style="--persona:${esc(p.accent_color)}">${ncAuthorAvatar(p)}<h3 class="user-content">${esc(p.display_name)}</h3><div class="small muted">@${esc(p.handle)} · ${esc(ncLabel(p.kind))}</div><p class="user-content">${esc(p.short_bio)}</p>${p.can_edit?'<span class="tag">EDIT</span>':''}</article>`).join('')}</div>`;ncBindActivation('[data-persona-open]',view,element=>go(`/personas/${element.dataset.personaOpen}`));if($('#persona-new'))$('#persona-new').onclick=()=>openPersonaEditor();}
async function openMembershipEditor(personaId, existing) {
  const data = await api('/api/personas?manage=1');
  const orgs = data.personas.filter(p => ['organization','gang','corporation','government','outlet'].includes(p.kind));
  const m = existing || {};
  const modal = openModal(`<h2>\ud83c\udfdb\ufe0f ${existing ? T('Edit Membership', '\u0418\u0437\u043c\u0435\u043d\u0438\u0442\u044c Membership') : T('New Membership', '\u041d\u043e\u0432\u044b\u0439 Membership')}</h2><div class="grid cols-2"><label class="f"><span>${T('Organization', '\u041e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0446\u0438\u044f')}</span><select id="ms-org">${orgs.map(o => '<option value="' + o.id + '" ' + (m.organization_persona_id === o.id ? 'selected' : '') + '>' + esc(o.display_name) + '</option>').join('')}</select></label><label class="f"><span>${T('Role Title', '\u0414\u043e\u043b\u0436\u043d\u043e\u0441\u0442\u044c')}</span><input id="ms-role" value="${esc(m.role_title || '')}" placeholder="${T('Fixer', '\u0424\u0438\u043a\u0441\u0435\u0440')}"></label><label class="f"><span>${T('Status', '\u0421\u0442\u0430\u0442\u0443\u0441')}</span><select id="ms-status">${['active','former','secret','expelled','deceased'].map(v => '<option ' + (m.status === v ? 'selected' : '') + '>' + v + '</option>').join('')}</select></label><label class="f"><span>${T('Visibility', '\u0412\u0438\u0434\u0438\u043c\u043e\u0441\u0442\u044c')}</span><select id="ms-vis">${['public','gm','classified'].map(v => '<option ' + (m.visibility === v ? 'selected' : '') + '>' + v + '</option>').join('')}</select></label></div><label class="f"><span>${T('Note', '\u0417\u0430\u043c\u0435\u0442\u043a\u0430')}</span><textarea id="ms-note">${esc(m.note || '')}</textarea></label><div class="row"><button id="ms-cancel">${T('Cancel', '\u041e\u0442\u043c\u0435\u043d\u0430')}</button>${existing ? '<button class="btn-danger" id="ms-del">' + T('Delete', '\u0423\u0434\u0430\u043b\u0438\u0442\u044c') + '</button>' : ''}<button class="btn-primary" id="ms-save">${T('Save', '\u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c')}</button></div>`, true);
  $('#ms-cancel', modal).onclick = closeModal;
  if ($('#ms-del', modal)) $('#ms-del', modal).onclick = async () => { try { await api('/api/personas/' + personaId + '/memberships/' + existing.id, { method: 'DELETE' }); closeModal(); route(); } catch (e) { toast(e.message, true); } };
  $('#ms-save', modal).onclick = async () => {
    const body = { member_persona_id: personaId, organization_persona_id: Number($('#ms-org', modal).value), role_title: $('#ms-role', modal).value, status: $('#ms-status', modal).value, visibility: $('#ms-vis', modal).value, note: $('#ms-note', modal).value };
    try { await api(existing ? '/api/personas/' + personaId + '/memberships/' + existing.id : '/api/personas/' + personaId + '/memberships', { method: existing ? 'PUT' : 'POST', body }); closeModal(); route(); } catch (e) { toast(e.message, true); }
  };
}

